#include <bits/stdc++.h>using namespace std;using ll = long long; void solve() {    ll s, k, m;    cin >> s >> k >> m;     ll flips = m / k;    ll x = flips * k;            ll y = m - x;                ll remaining;    if (flips % 2 == 0) {        remaining = max(0LL, s - y);    } else {        remaining = max(0LL, min(s, k) - y);    }      cout << remaining << "\n";} int main() {    ios_base::sync_with_stdio(false);    cin.tie(nullptr);     int t;    cin >> t;    while (t--) solve();     return 0;}